class Solution { fun regionsBySlashes(grid:Array<String>):Int{val n=grid.size;val size=3*n;val blocked=Array(size){BooleanArray(size)};for(r in 0 until n)for(c in 0 until n){val ch=grid[r][c];if(ch=='/'){blocked[3*r][3*c+2]=true;blocked[3*r+1][3*c+1]=true;blocked[3*r+2][3*c]=true}else if(ch.code==92){blocked[3*r][3*c]=true;blocked[3*r+1][3*c+1]=true;blocked[3*r+2][3*c+2]=true}};var regions=0;val directions=arrayOf(intArrayOf(1,0),intArrayOf(-1,0),intArrayOf(0,1),intArrayOf(0,-1));for(r in 0 until size)for(c in 0 until size)if(!blocked[r][c]){regions++;val queue=java.util.ArrayDeque<IntArray>();queue.addLast(intArrayOf(r,c));blocked[r][c]=true;while(queue.isNotEmpty()){val cell=queue.removeFirst();for(d in directions){val nr=cell[0]+d[0];val nc=cell[1]+d[1];if(nr in 0 until size&&nc in 0 until size&&!blocked[nr][nc]){blocked[nr][nc]=true;queue.addLast(intArrayOf(nr,nc))}}}};return regions} }
